{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Melagatran has human oral bioavailability of only 3–7% (0.9% after food), a direct clinical measurement far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Saquinavir (INVIRASE) has an average absolute oral bioavailability of 4% (range 1–9%) in humans, directly below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Olcegepant has absolute oral bioavailability <1% in humans, showing that potent drug-like molecules can have extremely low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "DX-9065a has human oral bioavailability of only 2–3% across multiple formulations, directly below the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "FK3453 was discontinued due to unexpectedly poor oral bioavailability attributed to aldehyde oxidase-mediated clearance, a relevant metabolic liability for aminoheterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Didanosine showed 38% ± 15% oral bioavailability as a solution with antacid in fasting patients, the only evidence at or above 20%; however, other didanosine records show 17–28% depending on conditions, so this is variable and not a robust high-F anchor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental evidence from human oral bioavailability studies points to F < 20%: melagatran 3–7%, saquinavir 4%, olcegepant <1%, DX-9065a 2–3%, FK3453 low, and danavorexton poor. The only borderline evidence (didanosine, 17–38%) is variable and condition-dependent, and is outweighed by the consistent low-F measurements. Therefore the query is predicted to have low oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement for the query molecule itself.",
    "The only borderline evidence (didanosine) is structurally dissimilar and highly variable by formulation/food status.",
    "Assay-transfer scores are high but do not encode chemical similarity; structural differences may reduce mechanistic transfer for specific low-F causes."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

